import pytest

from app.calc import mean


def test_mean_single_value():
    assert mean([7]) == 7


def test_mean_negative_and_fractional_values():
    assert mean([-2, 0, 3]) == pytest.approx(1 / 3)


def test_mean_empty_raises():
    with pytest.raises(ZeroDivisionError):
        mean([])

